SELECT *
FROM behavior_events
WHERE device_binding_id = #{deviceBindingId}
  AND event_id = #{eventId}
LIMIT 1

SELECT *
FROM behavior_events
WHERE device_binding_id = #{deviceBindingId}
  AND event_time >= #{fromTime}
  AND event_time <= #{toTime}
ORDER BY event_time ASC,
         CASE event_type WHEN 'CLOSE' THEN 0 WHEN 'OPEN' THEN 1 END ASC,
         received_at ASC,
         id ASC
